["stepgoals"] = "step\ntalk Frankal Stonebridge##15171\nSelect _\"Hello, Frankal. I've heard that you might have some information as to the whereabouts of Mistress Natalia Mar'alith.\"_ |gossip 116979\nSelect _\"That's what I like to hear.\"_ |gossip 117219\nSelect _\"That's odd.\"_ |gossip 117218\nSelect _\"You couldn't handle a lone night elf priestess?\"_ |gossip 117217\nSelect _\"I've been meaning to ask you about that monkey.\"_ |gossip 117216\nSelect _\"Then what?\"_ |gossip 114969\nSelect _\"What a story! So she went into Hive'Regal and that was the last you saw of her?\"_ |gossip 115222\nSelect _\"Thanks for the information, Frankal.\"_ |gossip 117417\nQuestion Frankal |q 8304/1 |goto Silithus/0 40.82,88.85",
